using UnityEngine;using UnityEngine.InputSystem;
[DefaultExecutionOrder(100)]
public class WoodlandCombatPresentation:MonoBehaviour {
 public WoodlandPlayer player;public Transform reloadModel,leftHand,magazine,oldMagazine,bandageArm,bandageHand,bandageWrap;public AudioClip[] casingSounds;
 public float reloadProgress;float reloadTime;public const float ReloadDuration=3.25f;public bool Reloading{get;private set;}bool holdBandage;Vector3 gunRest;Quaternion gunRotation;WoodlandCasing[] pool;int cursor;
 static float S(float x,float a,float b)=>Mathf.SmoothStep(0,1,Mathf.InverseLerp(a,b,x));
 void Start(){gunRest=player.rifle.localPosition;gunRotation=player.rifle.localRotation;pool=new WoodlandCasing[24];var mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));mat.color=new Color(.45f,.3f,.09f);mat.SetFloat("_Metallic",.8f);for(int i=0;i<pool.Length;i++){var g=GameObject.CreatePrimitive(PrimitiveType.Capsule);g.name="Spent rifle casing";g.transform.localScale=new Vector3(.009f,.023f,.009f);g.GetComponent<Renderer>().sharedMaterial=mat;var body=g.AddComponent<Rigidbody>();body.mass=.006f;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;var col=g.GetComponent<Collider>();foreach(var c in player.GetComponentsInChildren<Collider>(true))Physics.IgnoreCollision(col,c);pool[i]=g.AddComponent<WoodlandCasing>();pool[i].impacts=casingSounds;g.SetActive(false);}}
 public int EjectedCount{get;private set;}
 public int CasingImpactCount{get{int n=0;if(pool!=null)foreach(var shell in pool)if(shell)n+=shell.ImpactPlayCount;return n;}}
 public void Eject(){if(pool==null)return;var shell=pool[cursor++%pool.Length];shell.transform.SetPositionAndRotation(player.eye.transform.TransformPoint(new Vector3(.16f,-.12f,.48f)),Random.rotation);shell.Launch(player.eye.transform.TransformDirection(new Vector3(1.5f,1,.2f)));EjectedCount++;}
 public void BeginReload(){reloadTime=0;Reloading=true;}
 public void CancelReload(){Reloading=false;if(reloadModel)reloadModel.gameObject.SetActive(false);}
 void Update(){if(Reloading){reloadTime+=Time.deltaTime;reloadProgress=Mathf.Clamp01(reloadTime/ReloadDuration);if(!player.IsReloading)CancelReload();}var k=Keyboard.current;if(k==null)return;if(k.hKey.wasPressedThisFrame&&player.anatomy.NeedsBandage&&!player.fieldKit.Busy&&!player.IsReloading&&!(player.nodeRepair&&player.nodeRepair.Busy)&&!player.visorEffects.Busy){holdBandage=player.equipment.UseSupply("medical");}if(holdBandage&&!k.hKey.isPressed){player.equipment.CancelSupply();holdBandage=false;}if(!player.equipment.ActionBusy)holdBandage=false;}
 void LateUpdate(){if(Reloading){if(player.anatomy.Incapacitated){CancelReload();return;}PoseReload(reloadProgress);}bool dressing=player.equipment.ActionBusy&&(player.equipment.ActiveSupply=="medical"||player.equipment.ActiveSupply=="suit_patch");if(bandageArm)bandageArm.gameObject.SetActive(dressing);if(bandageHand)bandageHand.gameObject.SetActive(dressing);if(bandageWrap)bandageWrap.gameObject.SetActive(dressing);if(dressing){player.watch.gameObject.SetActive(false);player.rifle.gameObject.SetActive(false);player.adsRifle.gameObject.SetActive(false);player.focusRifle.gameObject.SetActive(false);float u=player.equipment.SupplyProgress;float lift=S(u,0,.18f)*(1-S(u,.82f,1));bandageArm.localPosition=new Vector3(-.12f,Mathf.Lerp(-.55f,-.24f,lift),.43f);bandageArm.localRotation=Quaternion.Euler(65,180,35);Vector3 dressingPoint=new Vector3(-.06f,Mathf.Lerp(-.55f,-.17f,lift),.43f);foreach(var r in bandageArm.GetComponentsInChildren<Renderer>())if(r.name=="olive sleeve"){bandageArm.position+=player.eye.transform.TransformPoint(dressingPoint)-r.bounds.center;break;}float spin=u*Mathf.PI*6;bandageHand.localPosition=dressingPoint+new Vector3(.08f+Mathf.Sin(spin)*.045f,.035f+Mathf.Cos(spin)*.035f,-.055f);bandageHand.localRotation=Quaternion.Euler(-60,180,75);bandageWrap.localPosition=dressingPoint;bandageWrap.localRotation=Quaternion.Euler(0,0,55);}}
 public void PoseReload(float u){if(!reloadModel)return;float blend=S(u,0,.14f)*(1-S(u,.86f,1));player.adsRifle.gameObject.SetActive(false);player.focusRifle.gameObject.SetActive(false);player.rifle.localPosition=gunRest+Vector3.down*.65f*blend;player.rifle.localRotation=gunRotation;player.rifle.gameObject.SetActive(u<.14f||u>.86f);reloadModel.gameObject.SetActive(u>=.14f&&u<=.86f);reloadModel.localRotation=Quaternion.Euler(0,180,Mathf.Lerp(0,-15,S(u,.14f,.26f))*(1-S(u,.75f,.86f)));reloadModel.localPosition=new Vector3(.035f,-.3f-.5f*((1-S(u,.1f,.23f))+S(u,.75f,.9f)),.92f);
 Vector3 seat=new Vector3(-.1285565f,.03839847f,.00167375f);float remove=S(u,.16f,.29f);oldMagazine.localPosition=seat+Vector3.down*.65f*remove;oldMagazine.gameObject.SetActive(u<.32f);float insert=S(u,.38f,.62f);magazine.localPosition=seat+new Vector3(-.08f,-.5f,.04f)*(1-insert);magazine.gameObject.SetActive(u>.35f);leftHand.localPosition=u<.32f?oldMagazine.localPosition:u<.68f?magazine.localPosition:Vector3.Lerp(seat,seat+new Vector3(-.23f,-.08f,-.11f),S(u,.68f,.84f));}
 void OnDestroy(){if(pool!=null)foreach(var c in pool)if(c)Destroy(c.gameObject);}
}
